export const LABS = ['BE-201', 'BE-202', 'AL-301'] as const;
export type LabCode = (typeof LABS)[number];

// Every LabCode is a string, so this widening is safe and checked (no cast).
const KNOWN: readonly string[] = LABS;

// Type guard: when it returns true, tsc narrows text to LabCode.
export function isLab(text: string): text is LabCode {
  return KNOWN.includes(text);
}

// The lab code from a query string such as 'lab=BE-201', or null when it is missing or unknown.
export function labFromQuery(query: string): LabCode | null {
  const text = new URLSearchParams(query).get('lab');
  if (text === null) return null;
  return isLab(text) ? text : null;
}

import { labFromQuery } from '../src/lab-query.ts';
import type { LabCode } from '../src/lab-query.ts';

const lab: LabCode | null = labFromQuery('lab=BE-201');
export { lab };

import type { LabCode } from '../src/lab-query.ts';

const lab: LabCode = 'BE-999'; // expect TS2322
export { lab };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { labFromQuery } from '../src/lab-query.ts';

test('a known lab is returned', () => assert.equal(labFromQuery('lab=AL-301'), 'AL-301'));
test('lower case is refused', () => assert.equal(labFromQuery('lab=be-201'), null));
test('an unknown lab is refused', () => assert.equal(labFromQuery('lab=BE-999'), null));
test('a missing lab is refused', () => assert.equal(labFromQuery('day=2026-11-02'), null));

