export type SlotCode = 'OFF_GRID' | 'END_BEFORE_START' | 'OUTSIDE_HOURS' | 'TOO_LONG';

// One message per slot code: as const keeps the texts literal and the object read-only;
// satisfies makes tsc check that EVERY SlotCode has a message.
export const SLOT_MESSAGES = {
  OFF_GRID: 'Start and end must be on the 30-minute grid.',
  END_BEFORE_START: 'The end time must be after the start time.',
  OUTSIDE_HOURS: 'Labs are open from 07:00 to 21:00.',
  TOO_LONG: 'A booking can last at most 4 hours.',
} as const satisfies Record<SlotCode, string>;

export function messageFor(code: SlotCode): string {
  return SLOT_MESSAGES[code];
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { messageFor } from '../src/messages.ts';

test('TOO_LONG has its message', () => assert.equal(messageFor('TOO_LONG'), 'A booking can last at most 4 hours.'));
test('OFF_GRID unchanged', () => assert.equal(messageFor('OFF_GRID'), 'Start and end must be on the 30-minute grid.'));

