// The erasable replacement for the enum: an ordinary object (it exists at runtime) ...
export const Status = { Pending: 'PENDING', Confirmed: 'CONFIRMED' } as const;
// ... and a type with the same name, derived from its values: 'PENDING' | 'CONFIRMED'.
export type Status = (typeof Status)[keyof typeof Status];

export function label(s: Status): string {
  return s === Status.Pending ? 'waiting for approval' : 'confirmed';
}

import { Status, label } from '../src/status.ts';

label('APPROVED'); // expect TS2345
Status.Pending = 'WAITING'; // expect TS2540

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Status, label } from '../src/status.ts';

test('names still work', () => assert.equal(label(Status.Pending), 'waiting for approval'));
test('a plain string from JSON is accepted', () => assert.equal(label('CONFIRMED'), 'confirmed'));
test('the values exist at runtime', () => assert.deepEqual(Object.values(Status), ['PENDING', 'CONFIRMED']));

